function setup() {
	createCanvas(windowWidth, windowHeight, WEBGL);
	dim = height / 20;
	scr = createGraphics(6.5 * dim, 30 * dim);
	tlogo.resize(0.7 * scr.width, 0);
	alogo.resize(1.5 * dim, 0);
	for (let ad of ads) {
		ad.resize(scr.width, 0);
	}
	scr.background(0);
	imageMode(CENTER);
	rectMode(CENTER);
	angleMode(DEGREES);
	makeDigits();
	makeSearch();
}

function draw() {
	background(0);
	orbitControl();
	ambientLight(80);
	pointLight(100, 100, 180, -height, -height, -height / 4);
	operateDigits();
	drawPhone();
	drawHand();
}

function drawPhone() {
	noStroke();
	fill(50);
	specularMaterial(200);
	shininess(5);
	box(7 * dim, 14 * dim, 0.8 * dim);
	box(6 * dim, 15 * dim, 0.8 * dim);
	for (let y of [-7 * dim, 7 * dim]) {
		for (let x of [-3 * dim, 3 * dim]) {
			push();
			translate(x, y);
			rotateX(90);
			cylinder(dim / 2, 0.8 * dim)
			pop();
		}
	}
	push();
	translate(0, 0, -0.401 * dim);
	scale(-1, 1, 1);
	imageMode(CENTER);
	image(alogo, 0, 0);
	pop();
	push();
	translate(2.5 * dim, -6.5 * dim, -0.401 * dim);
	fill(200, 20)
	rect(-dim / 4, dim / 4, 2 * dim, 2 * dim, dim / 4);

	push();
	translate(0, -0.25 * dim, 0)
	torus(dim / 2.6, dim / 18);
	rotateX(90);
	fill(0);
	cylinder(dim / 2.6, dim / 20);
	pop();
	push();
	translate(0, 0.7 * dim, 0)
	torus(dim / 2.6, dim / 18);
	rotateX(90);
	fill(0);
	cylinder(dim / 2.6, dim / 20);
	pop();

	push();
	translate(-0.7 * dim, 0.2 * dim, 0)
	rotateX(90);
	fill(255);
	cylinder(dim / 9, dim / 20);
	pop();

	pop();
	translate(0, 0, 0.401 * dim);
	fill(0);
	shininess(100);
	rect(0, 0, 6.8 * dim, 14.8 * dim, dim / 2);

	translate(0, 0, 0.01 * dim);
	image(scr, 0, 0, 6.5 * dim, 14.5 * dim, 0, topy, 6.5 * dim, 14.5 * dim, COVER);
	if (cos(fcount) < 0) topy += Math.pow(cos(fcount), 2) * height / 300 * fcv;
	topy = constrain(topy, 0, 15 * dim);
	if (frameCount > 60) fcount += fcv;
	if (fcount > 1170) {
		fcount = 1170;
		fcv = -2;
	}
	if (fcount < 0) {
		fcount = 0;
		fcv = 2;
	}
}

function drawHand() {
	push();
	translate(3 * dim, 3 * dim + dim * sin(fcount), 5.1 * dim + max(0, dim * cos(fcount)));
	fill(100);
	shininess(2)
	rotateX(130);
	rotateZ(-10 * sin(fcount));
	rotateY(-5 * sin(fcount))
	scale(-1, 1, 1);
	scale(height / 560);
	drawPalm();
	for (let d of digits) {
		d.show();
		if (frameCount > 20) d.flexback();
	}
	if (frameCount > 20) {
		digits[3].a1 = -15 + 20 * sin(fcount + 180);
		digits[3].a2 = -15 + 20 * sin(fcount + 180);
		digits[4].a2 = -10 + 20 * cos(fcount + 180);
		digits[0].a2 = 20 * cos(fcount + 135);
		digits[1].a2 = 20 * cos(fcount + 155);

	}

	pop();
}

function operateDigits() {
	if (keyIsDown(76)) {
		digits[0].a1 -= 4;
		digits[0].a2 -= 8;
	}
	if (keyIsDown(75)) {
		digits[1].a1 -= 4;
		digits[1].a2 -= 8;
	}
	if (keyIsDown(74)) {
		digits[2].a1 -= 4;
		digits[2].a2 -= 8;
	}
	if (keyIsDown(72)) {
		digits[3].a1 -= 4.5;
		digits[3].a2 -= 7;
	}
	if (keyIsDown(32)) {
		digits[4].a1 -= 5;
		digits[4].a2 -= 5;
	}
}
